// Normalize chat trigger output.
const chatInput = $json.chatInput || '';
const sessionId = $json.sessionId || 'web';
return [{ json: { query: chatInput, sessionId } }];

// Combine retrieved chunks into a tagged context block with source URLs.
const rows = $input.all().map(i => i.json);
const q = $('Prepare').first().json.query;
const sessionId = $('Prepare').first().json.sessionId;
let ctx = '';
const srcs = [];
rows.forEach((r, i) => {
  ctx += '[S' + (i + 1) + '] ' + (r.content || '') + '\n';
  if (r.source_url && !srcs.includes(r.source_url)) srcs.push(r.source_url);
});
return [{ json: { query: q, sessionId, context: ctx, sources: srcs } }];

// Assemble the strict grounding prompt: system rules + knowledge + history + question.
const ctx = $('Build context').first().json;
const histItems = $input.all().map(i => i.json).reverse();
const hist = histItems.map(h => (h.role === 'user' ? 'Visitor: ' : 'Assistant: ') + h.content).join('\n');
const rules = [
  'You are the chat assistant for ITC Immunity Therapy Center on PlacidWay (medical tourism).',
  'Answer the visitor question using ONLY the KNOWLEDGE excerpts below, taken from official PlacidWay pages.',
  'STRICT RULES:',
  '1. Never invent prices, clinics, treatments, or medical facts. Use only the KNOWLEDGE.',
  '2. If the answer is not in the KNOWLEDGE, say exactly: "I don\'t know the answer to that from the ITC pages. Please contact PlacidWay for a free quote." Do not guess.',
  '3. Prices: always include currency (USD) and context from the page, e.g. "starting from $18,995".',
  '4. If the visitor states a wrong price or fact, correct them politely using the KNOWLEDGE. Never agree with something false.',
  '5. Booking/appointments: you cannot book. Point them to the PlacidWay contact/quote form.',
  '6. Out-of-scope questions (weather, politics, etc.): politely decline and steer back to ITC treatments.',
  '7. Medical advice ("is it safe for my condition?"): give NO diagnosis or recommendation. Tell them to speak to their doctor and the ITC medical team. Add one brief line: "I\'m not a medical professional, so please consult your doctor."',
  '8. Use CONVERSATION SO FAR to resolve follow-ups (e.g. "what about recovery time?" refers to the previous treatment).',
  '9. Answer in the visitor\'s language (Spanish or Arabic questions get Spanish or Arabic answers, based on the English KNOWLEDGE).',
  '10. If the visitor wants a quote or to be contacted, end with: "If you\'d like a free quote, just share your name and email here."',
  '11. Be concise and warm.'
].join('\n');
const fullPrompt = rules + '\n\nKNOWLEDGE:\n' + ctx.context +
  '\n\nCONVERSATION SO FAR:\n' + (hist || '(none)') +
  '\n\nVisitor: ' + ctx.query + '\nAssistant:';
return [{ json: { fullPrompt, query: ctx.query, sessionId: ctx.sessionId, sources: ctx.sources } }];

// Extract answer text, append deterministic source citations, flag gaps and lead emails.
const j = $input.first().json;
let ans = '';
try { ans = j.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) { ans = ''; }
const prev = $('Build prompt').first().json;
if (!ans) ans = "I don't know the answer to that from the ITC pages. Please contact PlacidWay for a free quote.";
let out = ans.trim();
const saidIdk = /i don'?t know/i.test(out);
if (!saidIdk && prev.sources.length) {
  out += '\n\nSources:\n' + prev.sources.map(s => '- ' + s).join('\n');
}
const m = prev.query.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
return [{ json: { answer: out, query: prev.query, sessionId: prev.sessionId, unanswered: saidIdk, leadEmail: m ? m[1] : null } }];
